pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // deploy sGlp, usdc, rewardRouter, glpManager mocks are required for initialize
        // but since we only test owner(), we can skip full initialization if owner() works without it,
        // but the contract C uses Initializable and OwnableUpgradeable which require initialization.
        // We'll deploy mock contracts for required dependencies.
        // Since the test just checks owner(), we provide a minimal initialization.
        // However, C's initialize requires external contracts. To keep the test focused on owner(),
        // we can deploy a minimal mock for all required interfaces.
        // But the property only concerns owner() and ownership transfer, so we can initialize with mock addresses.
        MockERC20 sGlp = new MockERC20();
        MockERC20 usdc = new MockERC20();
        MockRewardRouter rewardRouter = new MockRewardRouter();
        MockGlpManager glpManager = new MockGlpManager();
        address dnGmxJuniorVault = address(new MockVault());
        address keeper = address(0x123);
        c = new C();
        c.initialize(
            IERC20(address(sGlp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(rewardRouter)),
            IGlpManager(address(glpManager)),
            dnGmxJuniorVault,
            keeper
        );
    }

    function testFuzz_property(address newOwner) public {
        // assume newOwner is not zero as transferOwnership forbids zero address
        vm.assume(newOwner != address(0));
        // The initial owner is the deployer of setUp, which is this contract.
        // We transfer ownership to newOwner.
        // The property: after transferOwnership(newOwner), owner() must return newOwner.
        // The bug always returns address(0).
        c.transferOwnership(newOwner);
        address currentOwner = c.owner();
        assertTrue(currentOwner == newOwner);
    }
}

