pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address originalOwner) public {
        vm.assume(originalOwner != address(0));
        vm.prank(originalOwner);
        c.initialize(
            IERC20(address(0x1)),
            IERC20(address(0x2)),
            IRewardRouterV2(address(0x3)),
            IGlpManager(address(0x4)),
            address(0x5),
            address(0x6)
        );
        // After initialization, the owner should be the caller.
        address currentOwner = c.owner();
        // In the correct contract, currentOwner == originalOwner.
        // In the buggy contract, currentOwner == address(0).
        // Now call an onlyOwner function as originalOwner; it should succeed in the correct contract.
        bool success = false;
        vm.prank(originalOwner);
        try c.grantAllowances() {
            success = true;
        } catch {
            success = false;
        }
        // The rule: if currentOwner == originalOwner, then the onlyOwner call must succeed.
        // In the buggy version, currentOwner == address(0) != originalOwner, so the implication is trivially true
        // (antecedent false), meaning assertTrue(true) would pass. We need a property that fails in the buggy version.
        // Instead, directly assert that the returned owner is the originalOwner.
        assertEq(currentOwner, originalOwner);
    }
}

