        c.initialize(
            IERC20(address(0x1)),
            IERC20(address(0x2)),
            IRewardRouterV2(address(0x3)),
            IGlpManager(address(0x4)),
            address(0x5),
            address(this)
        );

        // Attempt to transfer ownership to the fuzzed address
        bool success;
        if (newOwner == address(0)) {
            // Test zero address specifically
            success = false;
            try c.transferOwnership(address(0)) {
                success = true;
            } catch {}
        } else {
            success = false;
            try c.transferOwnership(newOwner) {
                success = true;
            } catch {}
