        // After any transfer attempt, if success is true, owner must not be zero
        // If newOwner is zero and success is true, this assertion fails (bug case)
        // If newOwner is zero and success is false (should happen in reference), assertion passes
        // If newOwner is non-zero and success is true, owner is newOwner (non-zero), assertion passes
        assertTrue(!success || c.owner() != address(0));
    }
}

