pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address randomCaller) public {
        // Ensure the caller is not the current owner
        vm.assume(randomCaller != c.owner());
        // Transfer ownership to address(0) using the true owner first
        // to trigger the bug condition (zero-address owner)
        vm.prank(c.owner());
        c.transferOwnership(address(0));
        // Now try to call transferOwnership from a non-owner.
        // Since the owner is now address(0), any address is a non-owner.
        vm.prank(randomCaller);
        bool ok = true;
        try c.transferOwnership(randomCaller) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the correct contract, calling transferOwnership from a non-owner
        // (which includes address(0)) must revert.
        // The buggy contract allows address(0) to act as owner, so a call
        // from a non-owner may succeed, violating this invariant.
        assertTrue(!ok, "transferOwnership by non-owner should revert");
    }
}

