    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address keeper, address dnGmxJuniorVault, address token, uint256 amount) public {
        // Restrict to valid addresses to avoid reverts during initialization.
        vm.assume(keeper != address(0));
        vm.assume(dnGmxJuniorVault != address(0));
        vm.assume(token != address(0));
        vm.assume(amount > 0);

        // Deploy a minimal mock that satisfies IERC20, IDnGmxJuniorVault, IRewardRouterV2, IGlpManager interfaces needed by initialize.
        MockDnGmxJuniorVault mockVault = new MockDnGmxJuniorVault();
        MockERC20 mockSGlp = new MockERC20();
        MockERC20 mockUsdc = new MockERC20();
        MockRewardRouter mockRouter = new MockRewardRouter();
        MockGlpManager mockGlpManager = new MockGlpManager();

        // We need to let the initialize succeed, but we are fuzzing the keeper that controls pause/unpause.
        // The initialize takes external contracts as arguments; we use the mocks.
        c.initialize(
            IERC20(address(mockSGlp)),
            IERC20(address(mockUsdc)),
            IRewardRouterV2(address(mockRouter)),
            IGlpManager(address(mockGlpManager)),
            address(mockVault),
            keeper
        );

        // The reference contract starts unpaused (by default).
        // Call unpauseDeposit as the keeper — this is a no-op if not paused, but in the buggy version paused() always returns true,
        // so _unpause() sets _paused to false, yet paused() still returns true.
        vm.prank(keeper);
        c.unpauseDeposit();

        // Now read paused(). Reference: false, Bug: true.
        bool isPaused = c.paused();
        assertTrue(!isPaused);
    }
}

