contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // initialize with minimal mocks to satisfy onlyInitializing and addresses
        // deploy mock tokens and router/glpManager with code so calls don't revert
        MockERC20 sGlp = new MockERC20();
        MockERC20 usdc = new MockERC20();
        MockRouter router = new MockRouter();
        MockGlpManager glpManager = new MockGlpManager();
        MockVault vault = new MockVault();
        glpManager.setVault(address(vault));
        c.initialize(
            IERC20(address(sGlp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(router)),
            IGlpManager(address(glpManager)),
            address(this), // dnGmxJuniorVault: we are vault
            address(this)  // keeper
        );
    }
    function testFuzz_property(bool initiallyPaused) public {
        // Setup: if initiallyPaused, pause; else ensure unpaused state
        if (initiallyPaused) {
            c.pauseDeposit();
        } else {
            // if paused, unpause; else keep unpaused
            if (c.paused()) {
                c.unpauseDeposit();
            }
        }
        // Now call executeBatchDeposit which may call _unpause internally
        // We need to ensure conditions for executeBatchDeposit are met
        // It requires block.timestamp > lastUnpauseTimestamp + 15 minutes
        // Warp far enough
        vm.warp(block.timestamp + 30 minutes);
        c.executeBatchDeposit();
        // After executeBatchDeposit, the contract should be unpaused regardless of initial state
        // because it calls _unpause if paused.
        bool isPausedAfter = c.paused();
        assertTrue(!isPausedAfter);
    }
}

